import tensorflow as tf
import tensorflow_federated as tff
from tensorflow_federated.python.learning import model as model_lib
from tensorflow_federated.python.learning import optimizer as optimizer_lib

def create_custom_finalizer(aggregation_fn, model_fn, optimizer_fn):
    # Define a custom finalizer using the provided aggregation function
    class CustomFinalizer(finalizers.Finalizer):
        def __init__(self, model, optimizer):
            self._model = model
            self._optimizer = optimizer

        @property
        def weights_type(self):
            return self._model.weights_type

        @property
        def weights(self):
            return self._model.weights

        @property
        def state_type(self):
            return self._model.state_type

        @property
        def state(self):
            return self._model.state

        @tf.function
        def __call__(self, server_state, result):
            aggregated_model_update = aggregation_fn(result)
            new_model_weights = self._model.weights.trainable
            optimizer_state = self._optimizer.variables()
            return tff.learning.ModelWeights(
                trainable=new_model_weights,
                non_trainable=server_state,
            ), optimizer_state

    # Create a tff.learning.Model instance using the custom finalizer
    class CustomModel(model_lib.Model):
        def __init__(self, model_fn, optimizer_fn):
            self._model_fn = model_fn
            self._optimizer_fn = optimizer_fn

        def forward_pass(self, batch, training=True):
            return self._model_fn().forward_pass(batch)

        def report_local_outputs(self):
            return self._model_fn().report_local_outputs()

        def trainable_variables(self):
            return self._model_fn().trainable_variables()

        def non_trainable_variables(self):
            return self._model_fn().non_trainable_variables()

        def create_optimizer(self):
            return optimizer_lib.build_optimizer_from_hparams(self._optimizer_fn())

        def initialize(self):
            return self._model_fn().initialize()

        @property
        def federated_output_computation(self):
            return CustomFinalizer(self._model_fn(), self._optimizer_fn())

    return CustomModel(model_fn, optimizer_fn)
