            if 'weight' in name:
                init_param(param, init_function=torch.nn.init.xavier_normal_)
            elif 'bias' in name:
                init_param(param, init_function=torch.nn.init.zeros_)

    def forward(self, input_data, hidden_state=None):
        # Perform forward propagation through the FNN
        output, new_hidden_state = self.fnn(input_data, hidden_state)

