```python
import torch
import torch.nn as nn
import torch.nn.functional as F

class AP1Function(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, grad):
        ctx.save_for_backward(input, grad)
        return input  # Placeholder operation for AP1

    @staticmethod
    def backward(ctx, grad_output):
        input, grad = ctx.saved_tensors
        # Custom gradient computation for AP1
        grad = grad + grad_output
        return grad, None

class AP2Function(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, grad, lr, curvature_bias):
        ctx.save_for_backward(input, grad)
        ctx.lr = lr
        ctx.curvature_bias = curvature_bias
        return input  # Placeholder operation for AP2

    @staticmethod
    def backward(ctx, grad_output):
        input, grad = ctx.saved_tensors
        lr = ctx.lr
        curvature_bias = ctx.curvature_bias
        # Custom gradient computation for AP2
        grad = grad - lr * (grad_output + curvature_bias * grad)
        return grad, None, None, None

class APFunction(nn.Module):
    def __init__(self, lr, curvature_bias):
        super(APFunction, self).__init__()
        self.is_first = True
        self.lr = lr
        self.curvature_bias = curvature_bias

    def forward(self, input):
        if self.is_first:
            self.is_first = False
            if not hasattr(self, 'grad') or self.grad.shape != input.shape:
                self.register_buffer('grad', torch.zeros(*input.shape))
            return AP1Function.apply(input, self.grad)
        else:
            self.is_first = True
            return AP2Function.apply(input, self.grad, self.lr, self.curvature_bias)

# Example usage
lr = 0.01
curvature_bias = 0.1
ap_function = APFunction(lr, curvature_bias)
input_tensor = torch.randn(3, 3, requires_grad=True)
output = ap_function(input_tensor)
output.mean().backward()
print(input_tensor.grad)
```
