import numpy as np

class AnomalyDetector:
    def __init__(self, threshold):
        self._threshold = threshold
        self._neg = None
        self._neg_size = 0

    def add_sample(self, s):
        if self._neg is None or self.__dist__(s, self._neg) > self._threshold:
            # train negative classifier
            self._neg_size += 1
            if self._neg is None:
                self._neg = s
            else:
                self._neg = self._neg + ((s - self._neg) / self._neg_size)

    def __dist__(self, x, y):
        return np.sqrt(np.sum((x - y) ** 2))
