import numpy as np

def calculate_bspline_curve(control_points, knot_vector, u):
    p = len(control_points) - 1  # Degree of the B-spline curve
    n = len(control_points)  # Number of control points
    m = len(knot_vector)  # Number of knots

    def basis_function(i, j, u):
        if j == 0:
            return 1 if knot_vector[i] <= u < knot_vector[i+1] else 0
        else:
            left_term = (u - knot_vector[i]) / (knot_vector[i+j] - knot_vector[i]) * basis_function(i, j-1, u)
            right_term = (knot_vector[i+j+1] - u) / (knot_vector[i+j+1] - knot_vector[i+1]) * basis_function(i+1, j-1, u)
            return left_term + right_term

    def calculate_point(u):
        point = np.zeros(len(control_points[0]))  # Initialize the point with zeros
        for i in range(n):
            point += basis_function(i, p, u) * control_points[i]
        return point

    return calculate_point(u)
```

This solution defines a function `calculate_bspline_curve` that takes in the control points, knot vector, and parameter `u`. It then calculates the B-spline curve at the given parameter `u` using the Cox-de Boor recursion formula and returns the coordinates of the point on the curve.

