class ArrayIterator:
    def __init__(self, array):
        self.array = array
        self.row = 0
        self.col = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.row < len(self.array) and self.col < len(self.array[self.row]):
            value = self.array[self.row][self.col]
            self.col += 1
            if self.col == len(self.array[self.row]):
                self.row += 1
                self.col = 0
            return value
        else:
            raise StopIteration

    def shape(self):
        return (len(self.array), len(self.array[0]))

    def flat(self):
        return [element for row in self.array for element in row]

    def __array__(self):
        import numpy as np
        return np.array(self.array)

# Example usage
arr = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
ar_iter = ArrayIterator(arr)

print(next(ar_iter))  # Output: 1
print(next(ar_iter))  # Output: 2
print(ar_iter.shape())  # Output: (3, 3)
print(ar_iter.flat())  # Output: [1, 2, 3, 4, 5, 6, 7, 8, 9]
print(ar_iter.__array__())  # Output: [[1 2 3]
                            #          [4 5 6]
                            #          [7 8 9]]
```

