import numpy
from rdkit import Chem
from rdkit.Chem.EState import EStateIndices
from rdkit.Chem.MolSurf import _LabuteHelper

def calculate_hybrid_estate_vsa_descriptors(smiles: str) -> dict:
    try:
        mol = Chem.MolFromSmiles(smiles)
        if mol is None:
            raise ValueError("Invalid SMILES string")

        estate_indices = EStateIndices(mol)
        vsa_contribs = _LabuteHelper(mol)

        hybrid_descriptors = {}
        for i in range(1, 13):  # Assuming 12 VSA descriptors
            hybrid_descriptors[f'EState_VSA{i}'] = estate_indices.GetLabuteAtomContrib(i) * vsa_contribs[i - 1]

        return hybrid_descriptors
    except Exception as e:
        return {"error": str(e)}
```

