import numpy as np

class Document:
    def __init__(self, text):
        self.text = text
        self.tensor = None

class DocumentProcessor:
    def __init__(self, documents):
        self.documents = [Document(doc) for doc in documents]

    def get_vocabulary(self):
        all_words = ' '.join([doc.text for doc in self.documents]).split()
        return {word: i+2 for i, word in enumerate(set(all_words))}

    def convert_text_to_tensor(self, vocab, max_length):
        for doc in self.documents:
            doc.tensor = [vocab.get(word, 1) for word in doc.text.split()][:max_length]

    def convert_tensor_to_text(self, vocab):
        for doc in self.documents:
            doc.text = ' '.join([key for key, value in vocab.items() if value in doc.tensor])

# Test the implementation
docs = ["hello world", "world is", "hello beautiful"]
test_docs = DocumentProcessor(docs)
vocab = test_docs.get_vocabulary()
test_docs.convert_text_to_tensor(vocab, max_length=1)

np.testing.assert_array_equal(test_docs.documents[0].tensor, [2])
np.testing.assert_array_equal(test_docs.documents[1].tensor, [3])
np.testing.assert_array_equal(test_docs.documents[2].tensor, [3])

test_docs.convert_tensor_to_text(vocab)

assert test_docs.documents[0].text == 'hello'
```
In this solution, we define a `Document` class to represent each document with its text and tensor attributes. The `DocumentProcessor` class is implemented with methods to process documents and convert text to tensors and vice versa. The provided code snippet's assertions are satisfied by the implemented methods.

