import torch

def compute_jacobian_sum(input_data, thetas):
    return torch.autograd.functional.jacobian(lambda x: thetas.squeeze() @ x, input_data).sum(dim=1, keepdim=True)

def compute_jacobian(input_data, thetas):
    return torch.autograd.functional.jacobian(lambda x: thetas @ x, input_data)

def compute_jacobian_matrix(x, model, norm):
    thetas = model.thetas
    nclass = thetas.size(-1)
    if norm == 1:
        DTh = compute_jacobian_sum(x, thetas)
    else:
        DTh = []
        for i in range(nclass):
            DTh.append(compute_jacobian(x, thetas[:,:,i]).unsqueeze(-1))
        DTh = torch.cat(DTh, 3)
    return DTh

# Example usage
# Assuming model and input_data are defined
norm = 1
jacobian_matrix = compute_jacobian_matrix(input_data, model, norm)
print(jacobian_matrix)
```

